I'll create a comprehensive Python decorators tutorial with detailed examples for each section.

```python
"""
Python Decorators: A Comprehensive Tutorial
===========================================

A decorator is a design pattern that allows you to modify or extend the behavior
of functions or classes without permanently modifying them. Decorators wrap another
function/class and allow you to execute code before and after the wrapped function runs.
"""

# ============================================================================
# 1. BASIC DECORATOR SYNTAX
# ============================================================================

print("=" * 60)
print("1. BASIC DECORATOR SYNTAX")
print("=" * 60)

# Simple function decorator
def simple_decorator(func):
    """A basic decorator that wraps a function."""
    def wrapper():
        print("Before function execution")
        func()
        print("After function execution")
    return wrapper

@simple_decorator
def say_hello():
    print("Hello, World!")

say_hello()
print()

# This is equivalent to:
# say_hello = simple_decorator(say_hello)


# Decorator with function arguments
def decorator_with_args(func):
    """Decorator that handles function arguments using *args and **kwargs."""
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__} with args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        print(f"{func.__name__} returned: {result}")
        return result
    return wrapper

@decorator_with_args
def add(a, b):
    return a + b

@decorator_with_args
def greet(name, greeting="Hello"):
    return f"{greeting}, {name}!"

result1 = add(5, 3)
result2 = greet("Alice", greeting="Hi")
print()


# Preserving function metadata with functools.wraps
from functools import wraps

def better_decorator(func):
    """Decorator that preserves original function metadata."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        """Wrapper function."""
        return func(*args, **kwargs)
    return wrapper

@better_decorator
def documented_function():
    """This function has documentation."""
    pass

print(f"Function name: {documented_function.__name__}")
print(f"Function docstring: {documented_function.__doc__}")
print()


# ============================================================================
# 2. DECORATORS WITH ARGUMENTS
# ============================================================================

print("=" * 60)
print("2. DECORATORS WITH ARGUMENTS")
print("=" * 60)

# Decorator factory - a function that returns a decorator
def repeat(times):
    """Decorator that repeats function execution."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for _ in range(times):
                result = func(*args, **kwargs)
                results.append(result)
            return results
        return wrapper
    return decorator

@repeat(times=3)
def say_hi(name):
    message = f"Hi, {name}!"
    print(message)
    return message

results = say_hi("Bob")
print(f"Results: {results}\n")


# Decorator with optional arguments
def smart_repeat(func=None, *, times=2):
    """Decorator that can be used with or without arguments."""
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            for _ in range(times):
                result = f(*args, **kwargs)
            return result
        return wrapper

    if func is None:
        # Called with arguments: @smart_repeat(times=3)
        return decorator
    else:
        # Called without arguments: @smart_repeat
        return decorator(func)

@smart_repeat
def function1():
    print("Called with default times")

@smart_repeat(times=4)
def function2():
    print("Called with times=4")

function1()
print()
function2()
print()


# Practical example: Rate limiting decorator
import time
from functools import wraps

def rate_limit(max_calls, period):
    """Limit function calls to max_calls per period (in seconds)."""
    def decorator(func):
        calls = []

        @wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            # Remove calls outside the current period
            calls[:] = [call for call in calls if call > now - period]

            if len(calls) >= max_calls:
                sleep_time = period - (now - calls[0])
                print(f"Rate limit reached. Sleeping for {sleep_time:.2f}s")
                time.sleep(sleep_time)
                calls.pop(0)

            calls.append(time.time())
            return func(*args, **kwargs)

        return wrapper
    return decorator

@rate_limit(max_calls=3, period=5)
def api_call(endpoint):
    print(f"Calling API endpoint: {endpoint}")
    return {"status": "success"}

# This will allow 3 calls quickly, then rate limit
for i in range(5):
    api_call(f"/data/{i}")
print()


# ============================================================================
# 3. CLASS DECORATORS
# ============================================================================

print("=" * 60)
print("3. CLASS DECORATORS")
print("=" * 60)

# Class as a decorator
class CountCalls:
    """Decorator class that counts function calls."""
    def __init__(self, func):
        self.func = func
        self.count = 0
        wraps(func)(self)  # Preserve metadata

    def __call__(self, *args, **kwargs):
        self.count += 1
        print(f"Call {self.count} to {self.func.__name__}")
        return self.func(*args, **kwargs)

@CountCalls
def process_data(data):
    return data.upper()

process_data("hello")
process_data("world")
process_data("python")
print()


# Decorator for classes
def singleton(cls):
    """Decorator that converts a class into a singleton."""
    instances = {}

    @wraps(cls)
    def get_instance(*args, **kwargs):
        if cls not in instances:
            instances[cls] = cls(*args, **kwargs)
        return instances[cls]

    return get_instance

@singleton
class Database:
    def __init__(self):
        print("Initializing database connection")
        self.connection = "Connected"

# Both variables reference the same instance
db1 = Database()
db2 = Database()
print(f"db1 is db2: {db1 is db2}")
print()


# Class decorator that adds methods
def add_repr(cls):
    """Decorator that adds a __repr__ method to a class."""
    def __repr__(self):
        attrs = ', '.join(f"{k}={v!r}" for k, v in self.__dict__.items())
        return f"{cls.__name__}({attrs})"

    cls.__repr__ = __repr__
    return cls

@add_repr
class Person:
    def __init__(self, name, age):
        self.name = name
        self.age = age

person = Person("Alice", 30)
print(repr(person))
print()


# ============================================================================
# 4. BUILT-IN DECORATORS
# ============================================================================

print("=" * 60)
print("4. BUILT-IN DECORATORS")
print("=" * 60)

# @property - converts method to read-only attribute
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        """Get the radius."""
        return self._radius

    @radius.setter
    def radius(self, value):
        """Set the radius with validation."""
        if value < 0:
            raise ValueError("Radius cannot be negative")
        self._radius = value

    @property
    def area(self):
        """Calculate area (read-only)."""
        return 3.14159 * self._radius ** 2

    @property
    def circumference(self):
        """Calculate circumference (read-only)."""
        return 2 * 3.14159 * self._radius

circle = Circle(5)
print(f"Radius: {circle.radius}")
print(f"Area: {circle.area:.2f}")
print(f"Circumference: {circle.circumference:.2f}")

circle.radius = 10
print(f"New area: {circle.area:.2f}")
print()


# @staticmethod - method that doesn't receive instance or class as first argument
# @classmethod - method that receives class as first argument
class MathOperations:

    @staticmethod
    def add(x, y):
        """Static method - doesn't need instance or class."""
        return x + y

    @classmethod
    def multiply(cls, x, y):
        """Class method - receives class as first argument."""
        print(f"Called from class: {cls.__name__}")
        return x * y

    def divide(self, x, y):
        """Regular instance method."""
        return x / y

# Static method can be called without instance
print(f"Static method: {MathOperations.add(5, 3)}")

# Class method can be called without instance
print(f"Class method: {MathOperations.multiply(4, 7)}")

# Instance method requires an instance
math_ops = MathOperations()
print(f"Instance method: {math_ops.divide(10, 2)}")
print()


# @abstractmethod - from abc module for abstract base classes
from abc import ABC, abstractmethod

class Shape(ABC):
    """Abstract base class for shapes."""

    @abstractmethod
    def area(self):
        """Calculate area - must be implemented by subclasses."""
        pass

    @abstractmethod
    def perimeter(self):
        """Calculate perimeter - must be implemented by subclasses."""
        pass

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

    def area(self):
        return self.width * self.height

    def perimeter(self):
        return 2 * (self.width + self.height)

rect = Rectangle(4, 5)
print(f"Rectangle area: {rect.area()}")
print(f"Rectangle perimeter: {rect.perimeter()}")
print()


# ============================================================================
# 5. PRACTICAL EXAMPLES
# ============================================================================

print("=" * 60)
print("5. PRACTICAL EXAMPLES")
print("=" * 60)

# Example 1: Timing decorator
import time
from functools import wraps

def timer(func):
    """Measure execution time of a function."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f"{func.__name__} took {end - start:.4f} seconds")
        return result
    return wrapper

@timer
def slow_function():
    time.sleep(0.1)
    return "Done"

slow_function()
print()


# Example 2: Memoization (caching) decorator
def memoize(func):
    """Cache function results to avoid redundant calculations."""
    cache = {}

    @wraps(func)
    def wrapper(*args):
        if args not in cache:
            cache[args] = func(*args)
            print(f"Computed {func.__name__}{args}")
        else:
            print(f"Retrieved from cache: {func.__name__}{args}")
        return cache[args]

    return wrapper

@memoize
def fibonacci(n):
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

print(f"Fibonacci(10) = {fibonacci(10)}")
print(f"Fibonacci(10) = {fibonacci(10)}")  # Retrieved from cache
print()


# Example 3: Authentication/Authorization decorator
def require_auth(required_role):
    """Check if user has required role before executing function."""
    def decorator(func):
        @wraps(func)
        def wrapper(user, *args, **kwargs):
            if not hasattr(user, 'role'):
                raise ValueError("User object must have 'role' attribute")

            if user.role != required_role:
                raise PermissionError(
                    f"User role '{user.role}' insufficient. "
                    f"Required: '{required_role}'"
                )

            return func(user, *args, **kwargs)
        return wrapper
    return decorator

class User:
    def __init__(self, name, role):
        self.name = name
        self.role = role

@require_auth("admin")
def delete_database(user):
    return f"{user.name} deleted the database"

@require_auth("user")
def read_data(user):
    return f"{user.name} read the data"

admin = User("Alice", "admin")
regular_user = User("Bob", "user")

try:
    print(delete_database(admin))  # Success
    print(read_data(regular_user))  # Success
    print(delete_database(regular_user))  # Will raise PermissionError
except PermissionError as e:
    print(f"Error: {e}")
print()


# Example 4: Retry decorator with exponential backoff
import random

def retry(max_attempts=3, delay=1, backoff=2):
    """Retry function on failure with exponential backoff."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempt = 1
            current_delay = delay

            while attempt <= max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempt == max_attempts:
                        print(f"Failed after {max_attempts} attempts")
                        raise

                    print(f"Attempt {attempt} failed: {e}. "
                          f"Retrying in {current_delay}s...")
                    time.sleep(current_delay)
                    current_delay *= backoff
                    attempt += 1

        return wrapper
    return decorator

@retry(max_attempts=3, delay=0.1, backoff=2)
def unreliable_api_call():
    """Simulates an API call that fails randomly."""
    if random.random() < 0.7:  # 70% failure rate
        raise ConnectionError("Network error")
    return "Success!"

try:
    result = unreliable_api_call()
    print(f"Result: {result}")
except ConnectionError:
    print("All retry attempts exhausted")
print()


# Example 5: Validation decorator
def validate_types(**type_hints):
    """Validate function argument types."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Get function signature
            import inspect
            sig = inspect.signature(func)
            bound_args = sig.bind(*args, **kwargs)
            bound_args.apply_defaults()

            # Validate types
            for arg_name, arg_value in bound_args.arguments.items():
                if arg_name in type_hints:
                    expected_type = type_hints[arg_name]
                    if not isinstance(arg_value, expected_type):
                        raise TypeError(
                            f"Argument '{arg_name}' must be {expected_type.__name__}, "
                            f"got {type(arg_value).__name__}"
                        )

            return func(*args, **kwargs)
        return wrapper
    return decorator

@validate_types(name=str, age=int, score=float)
def register_student(name, age, score):
    return f"Registered {name} (age {age}) with score {score}"

try:
    print(register_student("Alice", 20, 95.5))  # Valid
    print(register_student("Bob", "twenty", 88.0))  # Invalid - will raise TypeError
except TypeError as e:
    print(f"Validation error: {e}")
print()


# Example 6: Deprecation warning decorator
import warnings

def deprecated(reason):
    """Mark function as deprecated."""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"{func.__name__} is deprecated. {reason}",
                category=DeprecationWarning,
                stacklevel=2
            )
            return func(*args, **kwargs)
        return wrapper
    return decorator

@deprecated("Use new_function() instead")
def old_function():
    return "This is the old way"

# This will show a deprecation warning
result = old_function()
print(f"Result: {result}")
print()


# Example 7: Context manager decorator
from contextlib import contextmanager

@contextmanager
def temporary_value(obj, attr, new_value):
    """Temporarily change an object's attribute."""
    old_value = getattr(obj, attr)
    setattr(obj, attr, new_value)
    try:
        yield obj
    finally:
        setattr(obj, attr, old_value)

class Config:
    debug = False

config = Config()
print(f"Debug mode: {config.debug}")

with temporary_value(config, 'debug', True):
    print(f"Debug mode (inside context): {config.debug}")

print(f"Debug mode (after context): {config.debug}")
print()


# Example 8: Chaining multiple decorators
@timer
@memoize
@validate_types(n=int)
def expensive_calculation(n):
    """Multiple decorators applied in order (bottom to top)."""
    time.sleep(0.05)  # Simulate expensive operation
    return n ** 2

print("First call:")
result1 = expensive_calculation(10)
print(f"Result: {result1}\n")

print("Second call (cached):")
result2 = expensive_calculation(10)
print(f"Result: {result2}\n")


print("=" * 60)
print("TUTORIAL COMPLETE")
print("=" * 60)
print("""
Key Takeaways:
1. Decorators wrap functions/classes to modify their behavior
2. Use @wraps to preserve function metadata
3. Decorator factories allow parameterized decorators
4. Class decorators can maintain state
5. Python has useful built-in decorators (@property, @staticmethod, etc.)
6. Decorators enable clean, reusable patterns (caching, timing, validation, etc.)
7. Multiple decorators can be chained together
8. Always consider the order when stacking decorators
""")
